import { useState, useCallback, memo } from 'react';
import '../styles/searchForm.css';

const cities = [
  'Москва', 'Санкт-Петербург', 'Казань', 'Новосибирск',
  'Екатеринбург', 'Краснодар', 'Сочи', 'Нижний Новгород', 'Стерлитамак'
];

const SearchForm = memo(({ onSearch, onInputChange, wide, isLoading }) => {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [date, setDate] = useState('');
  const [isFocused, setIsFocused] = useState(false);

  const handleSubmit = useCallback((e) => {
    e.preventDefault();
    if (!isLoading) onSearch({ from, to, date });
  }, [from, to, date, onSearch, isLoading]);

  const filterCities = useCallback((input) => 
    cities.filter(city => city.toLowerCase().includes(input.toLowerCase())), []);

  const handleInput = useCallback((e) => {
    onInputChange();
    const { name, value } = e.target;
    if (name === 'from') setFrom(value);
    if (name === 'to') setTo(value);
    if (name === 'date') setDate(value);
  }, [onInputChange]);

  return (
    <div className="search-form-container">
      <form 
        onSubmit={handleSubmit}
        className={`search-form ${wide ? 'wide' : ''} ${isFocused ? 'focused' : ''}`}
        onFocus={() => setIsFocused(true)}
        onBlur={() => setIsFocused(false)}
      >
        <h2 className="form-title">Поиск билетов</h2>
        
        <div className="form-grid">
          <div className="input-group">
            <label>Откуда</label>
            <div className="input-wrapper">
              <input
                value={from}
                onChange={handleInput}
                name="from"
                placeholder="Город отправления"
                autoComplete="off"
              />
            </div>
          </div>

          <div className="input-group">
            <label>Куда</label>
            <div className="input-wrapper">
              <input
                value={to}
                onChange={handleInput}
                name="to"
                placeholder="Город прибытия"
                autoComplete="off"
              />
            </div>
          </div>

          <div className="input-group">
            <label>Дата</label>
            <div className="input-wrapper">
              <input
                type="date"
                value={date}
                onChange={handleInput}
                name="date"
                min={new Date().toISOString().split('T')[0]}
              />
            </div>
          </div>
        </div>

        <button 
          type="submit" 
          className="search-button"
          disabled={!from || !to || isLoading}
        >
          {isLoading ? 'Загрузка...' : 'Найти билеты'}
        </button>
      </form>
    </div>
  );
});

export default SearchForm;
